algorithms.pseudocode:
Input: forms {c -> TropicalAffineForm}
Output: list of (assignment, polyhedron) pairs

for each assignment σ in ∏_c {1..K_c}:
  halfspaces = []
  for each class c:
    for each term k ≠ σ(c):
      w = slopes[c,σ(c)] - slopes[c,k]
      b = intercepts[c,σ(c)] - intercepts[c,k]
      halfspaces.append(AffineHalfspace(w, b))
  yield (σ, Polyhedron(halfspaces))
